```json
{"thought": "The goal is to find a path from src to dst that maximizes the minimum edge weight along the path (the 'bottleneck' capacity). This is a classic maximum capacity path problem. I can solve this using a modified Dijkstra's algorithm (using a max-priority queue) or by binary searching over the possible weight values and using BFS/DFS for reachability. Modified Dijkstra is more efficient. I'll implement it now.", "action": {"tool": "write_file", "args": {"path": "src/routekit/heaviest_route.py", "content": "from __future__ import annotations

import heapq
from typing import List, Mapping, Optional, Tuple


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    """
    Find the route that allows the heaviest truck from ``src`` to ``dst``.

    ``limits`` has the shape of an adjacency map, but each value is the weight limit of
    the road in tonnes (a positive integer). The load a route allows is the smallest
    limit along it. Returns ``(max_load, path)`` for a route whose allowed load is as
    large as possible, with ``path`` listing the depot codes from ``src`` to ``dst``.
    Returns None if ``dst`` cannot be reached. Several routes may allow the same load;
    the result must not depend on dict insertion order.

    Raises KeyError if ``src`` or ``dst`` is not in ``limits`` and ValueError if
    ``src == dst``.

    Example:
        limits = {"A": {"B": 40, "C": 12}, "B": {"A": 40, "C": 30}, "C": {"A": 12, "B": 30}}
        heaviest_route(limits, "A", "C") == (30, ["A", "B", "C"])
    """
    if src == dst:
        raise ValueError("src and dst must be different")
    if src not in limits:
        raise KeyError(f"src {src} not found in limits")
    if dst not in limits:
        raise KeyError(f"dst {dst} not found in limits")

    # Max-priority queue stores (-capacity, current_node, path)
    # We use negative capacity because heapq is a min-priority queue
    pq = [(-float('inf'), src, [src])]
    visited = {}

    while pq:
        neg_cap, u, path = heapq.heappop(pq)
        cap = -neg_cap

        if u == dst:
            return (int(cap) if cap != float('inf') else 0, path)

        if u in visited and visited[u] >= cap:
            continue
        visited[u] = cap

        for v, weight in limits.get(u, {}).items():
            # The capacity of the path to v is the min of the capacity to u and the edge (u, v)
            new_cap = min(cap, weight)
            if v not in visited or visited[v] < new_cap:
                heapq.heappush(pq, (-new_cap, v, path + [v]))

    return None
"}}}
